package com.taska.domain.planningcalendar;
import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/planning-calendars") @RequiredArgsConstructor public class PlanningCalendarController { private final PlanningCalendarService service; @GetMapping public List<PlanningCalendarDto> all(){return service.all();} @GetMapping("/{id}") public PlanningCalendarDto get(@PathVariable UUID id){return service.get(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) public PlanningCalendarDto create(@Valid @RequestBody PlanningCalendarRequest r){return service.create(r);}@PutMapping("/{id}") public PlanningCalendarDto update(@PathVariable UUID id,@Valid @RequestBody PlanningCalendarRequest r){return service.update(id,r);} }
